type RoleId = "borrower" | "investor";
interface Customer { readonly name: string; balance: number }
const roles = new WeakMap<Customer, Map<RoleId, object>>();    // core owns its role registry
function addRole<R extends object>(core: Customer, id: RoleId, make: (core: Customer) => R): R {
  const set = roles.get(core) ?? new Map<RoleId, object>();
  roles.set(core, set);
  if (!set.has(id)) set.set(id, make(core));
  return set.get(id) as R;
}
const borrower = addRole(customer, "borrower", core => ({
  borrow: (amount: number) => `${core.name} borrows ${amount}`,  // role view over the core
}));
